parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "exactitud_factual": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5,
      "description": "Exactitud factual según la rúbrica, de 1 a 5"
    },
    "estado_veredicto": {
      "type": "string",
      "enum": [
        "ACEPTADO",
        "CORREGIR",
        "RECHAZADO"
      ]
    },
    "categoria_error": {
      "type": "string",
      "enum": [
        "NINGUNO",
        "DATO_INCORRECTO",
        "DATO_NO_RESPALDADO",
        "OMISION",
        "FORMATO_VOZ",
        "PROMESA_RIESGOSA",
        "FUERA_DE_AMBITO"
      ]
    },
    "critica": {
      "type": "string",
      "description": "Qué corregir, en una o dos frases"
    }
  },
  "required": [
    "exactitud_factual",
    "estado_veredicto",
    "categoria_error",
    "critica"
  ],
  "additionalProperties": false
}
